import numpy as np

def feature(item, bins, capacity):
    """Complementarity: for a one-axis-heavy item, how much the bin's used space is heavy on the item's light axis."""
    cap = np.asarray(capacity, dtype=float)
    it = np.asarray(item, dtype=float)
    frac = it / cap
    hi = int(np.argmax(frac))
    lo = 1 - hi
    active = (frac.max() >= 0.4) and (frac.min() < 0.4)
    if not active:
        return np.zeros(bins.shape[0])
    used = cap - bins
    return (used[:, lo] / cap[lo]) - (used[:, hi] / cap[hi])

