import numpy as np

def feature(item, bins, capacity):
    """Headroom for one more small job on both axes after placing this small item."""
    small = (item < 0.25 * capacity).all()
    if not small:
        return np.zeros(bins.shape[0])
    r = np.clip(bins - item, 0, None)
    need = 0.2 * capacity
    ratio = r / need
    lo = np.minimum(np.minimum(ratio[:, 0], ratio[:, 1]), 1.0)
    hi = np.maximum(ratio[:, 0], ratio[:, 1])
    return lo - np.maximum(0.0, 1.0 - hi)

